    ox,oy=[(0,0),(0,1199),(792,0),(792,1199)][k-1]; f=1090/1650; sx,sy=0,0
    return (p,int((x1+ox)*f+sx),int((y1+oy)*f+sy),int((x2+ox)*f+sx),int((y2+oy)*f+sy))
