psg('日本是世界第三大經濟體，也是七大工業國組織的成員，該國是世界先進國家之一，也是亞洲最發達的國家之一，圖是日本主要工業區分布圖。')
M=P(16,4,378,155,708,398)
ch('日本工業發展的優勢「不包括」下列何者？',['豐富的礦產資源','優異的研發能力','技術優良的勞工','四面環海的環境'],1,'日本並未擁有豐富的礦產資源。')
ch('日本的主要工業區多集中在哪一大島上？',['四國','九州','本州','北海道'],3,'多數工業區位在本州島上。',img=M)
ch('根據日本國土交通省統計，2024 年 7 月在全國六大港口的貨櫃總量中，東京港占比最高，約為 30%。上述港口的位置，應位於圖中哪一地區？',J,1,'東京位於甲（京濱工業區）。',img=M)
ch('【素養】日本部分企業將生產部門轉移到東南亞的越南，完成的商品會以貨輪送回日本。依據位置判斷，這些貨輪離開越南的港口後，最可能朝哪一方向航行？',['東北方','西北方','東南方','西南方'],1,'越南位於日本的西南方，要前往日本須朝東北方前進。')
endp()

sec('第9回 地理 第二篇1～2章 複習')
ch('圖是亞洲某半島上的重要界標，圖中數據呈現的是緯度。依此判斷，該界標最可能位於亞洲哪一地區？',['北亞','西亞','東北亞','東南亞'],3,'北緯 38 度線為南、北韓的分界，位於東北亞。',img=P(17,1,655,540,770,725))
ch('每年的 11～12 月，南韓會在氣象圖上提供相關資訊給民眾參考進行各種蔬菜發酵的時間。影響此料理發展的背景因素最可能為下列何者？',['氣候悶熱，吃泡菜可排除熱氣','冬季氣候嚴寒，作物生長不易','昔日戰亂多，泡菜易攜帶儲存','居橋梁位置，受中日文化影響'],2,'泡菜的發展背景主要是因為南韓緯度位置較高，冬季不易生長蔬菜，故秋收後將蔬菜發酵製成泡菜可以儲存較久。')
ch('一般人都以為儒家是中國特有的文化，事實上受到中華文化影響深遠的日本及韓國至今仍會舉行祭孔典禮。上述提及典禮的舉行地區位於圖中何地？',J,1,'日本及韓國位於東北亞，即圖中甲。',img=P(17,1,510,1050,768,1250))
ch('日本前總理大臣指出：在機器人技術的提升與應用，將會解決服務產業低產能的課題，而工業與製造業上更廣泛的機器人應用，也將促成生產線產能提升，機器人是日本為解決人口問題的重要策略手段。上文中的人口問題包括下列哪一項？',['人口總數多','高齡化社會','性別比失衡','城鄉差距大'],2,'日本人口高齡化，勞動力不足，故以機器人補足。')
ch('賞秋楓和春櫻是日本民眾的重要活動，當地賞櫻時間是愈北愈晚，賞楓時間則是愈北愈早，影響此差異的共同因素為何？',['地勢高低','人口密度','緯度高低','距海遠近'],3,'櫻花在緯度較低的地區較早開花，而楓葉則是緯度較高的地區愈早楓紅，因此與緯度高低有關。')
ch('「這個國家的經濟政策採取扶植大型企業的模式，2023 年，此國的前十大企業營收占該國國內生產毛額的 48%，其中三星電子比例更高達全國的 14%。」上文中的國家應為何者？',['日本','北韓','南韓','中國'],3,'可以由扶植大型企業、三星電子判斷應為南韓。')
ch('【進階】日本地震調查委員會於 2025 年 1 月 15 日指出，圖中斜線地區未來 30 年內發生規模 8 至 9 地震的機率約為 80%。依據圖中資訊判斷，該區的地震與哪兩個板塊間的活動有關？',['歐亞板塊、非洲板塊','歐亞板塊、太平洋板塊','歐亞板塊、菲律賓海板塊','太平洋板塊、菲律賓海板塊'],3,'圖中斜線地區最接近歐亞板塊及菲律賓海板塊的範圍。',img=P(17,2,435,800,765,1065))
ch('近年來風靡亞洲的韓劇自從法規放寬後，許多南韓的大型企業透過贊助影視業，要求將其產品在劇中曝光。下列哪一產品可能會最常出現在韓劇中？',['現代汽車','華碩電腦','任天堂遊戲機','鬼滅之刃漫畫書'],1,'現代汽車為南韓品牌。')
ch('【進階】朝鮮半島的脊梁山脈──太白山脈位居半島東側，自北韓蓋馬高原東緣，一路延伸至南韓的釜山市附近，長達 400 餘公里，此一空間分布與該地區的何種地理現象的關係最密切？',['主要河川多數注入黃海','工業集中在日本海沿岸','北韓的經濟以農業為主','太白山東側人口密度高'],1,'太白山位於半島東側，地勢東高西低，故主要河川皆注入半島西側的黃海海域。')
ch('【進階】圖是小勳某日在報章媒體中見到的標題（四大財閥：三星、現代汽車、SK、LG），由於標題部分內容被撕毀，依據其他內容判斷，被撕毀的部分應為下列何者？',['日本','北韓','南韓','中國'],3,'可以從三星、SK 判斷應為南韓。',img=P(17,3,480,985,718,1220))
ch('【進階】日本主要工業區集中在本州靠近太平洋的沿岸，如：京濱、東海、名古屋等地。此一空間分布主要與下列何者關係最密切？',['動力充沛','勞力低廉','交通便利','原料豐富'],3,'日本缺乏礦產資源，原料需自海外進口，產品出口到國外，選擇在本州靠近太平洋的沿岸具有交通便利優勢。')
ch('【進階】圖是三個屬於溫帶季風氣候區的首都位置，依圖中內容判斷，有關這三座城市的氣候特徵之描述，下列何者最正確？',['日溫差：乙＞甲＞丙','年溫差：甲＞乙＞丙','冬季氣溫：丙＞乙＞甲','年降水量：甲＞乙＞丙'],4,'日本受海洋影響顯著，因此年降水量最充沛，而北京並未濱臨海洋，因此年降水量最少。',img=P(17,4,400,220,718,475))
ch('北韓由於發展核武，受到國際間的經濟制裁，為了推動觀光業，該國積極建設，其中馬息嶺滑雪場即是為了因應此一政策而興建。冬季是該景點的旺季，這時北韓的天氣主要受下列哪一項氣候因素的影響？',['黑潮支流','滯留鋒面','東北季風','蒙古高壓'],4,'冬季朝鮮半島受到蒙古高壓的影響較大。')
ch('「根據《動畫產業報告 2023》指出，日本動畫市場在該年度產值達 2 兆 9,277 億日圓，較前一年成長 6%，與 2013 年相比成長了 2 倍。」文中提及的產值最「不可能」由下列哪一部分所貢獻？',['電玩遊戲','人工智慧','真人化電影','圖像授權周邊'],2,'(B)屬於高科技產業。')
ch('韓劇《愛的迫降》講述南韓富可敵國的財團千金，因為一場飛行傘意外入境北韓，遇上身為北韓軍官的男主角，展開一段跨越國界的愛情故事。故事中的兩個國家大致以下列哪一條緯線為分界線？',['30°N','38°N','45°N','60°N'],2,'南、北韓大致以北緯 38 度為分界。')
ch('圖是近年來臺灣相當熱賣的商品（Switch 遊戲機）。該商品是由下列哪一公司所生產？',['南韓三星','美國蘋果','中國華為','日本任天堂'],4,'Switch 為日本任天堂所生產。',img=P(18,1,520,60,760,270))
ch('日本的漁獲產量名列世界前茅，該國漁業發達的原因「不包括」下列何者？',['近太平洋漁場','沿海寒暖流交會','海岸線曲折多港灣','漁業人口比例最高'],4,'(A)(B)(C)皆為日本漁業發達的自然條件。')
ch('【素養】南韓的鐵路密度高，其中京釜線是南韓相當重要的鐵路，該路線連結南韓首都與最大港口──釜山。依據上述判斷，京釜線的路線最可能為下列何者？（選項見圖）',G,1,'南韓的首都為首爾，位於朝鮮半島西北沿海地區，釜山則位於半島東南沿海地區，故選(A)。',img=P(18,1,185,640,600,1080))
ch('【素養】朝鮮半島上的北韓，其農業發展條件相較南韓顯得不利，經常有糧荒問題的發生。此現象產生的原因與下列何者的關連性最小？',['地形','緯度','盛行風向','經濟制度'],3,'南北韓均屬於溫帶季風氣候，盛行風向是相同的，北韓較多山且緯度高，加上採行共產主義，因此饑荒相對嚴重。')
ch('圖為日本傳統美食示意圖，呈現其獨特風味。該國之所以會出現此一飲食文化的主要影響因素為何？',['屬溫帶季風氣候區，適合生食','位居板塊接觸帶上，土壤貧瘠','四面環海，且有寒暖洋流交會','夏熱冬寒，氣候較同緯度暖溼'],3,'日本漁業發達，而該產業發達與四面環海且沿海有寒暖洋流交會有關。',img=P(18,2,495,145,770,360))
ch('【進階】根據媒體報導，日本在 2025 年將面臨近 40 萬名照顧服務員人力短缺，因此政府提出積極投入開發「看護機器人」，希望藉此解決勞動力不足的問題，並提升長照品質。依據工業性質判斷，日本大力發展的該產業與下列哪一項性質相同？',['鋼鐵工業','紡織工業','石化工業','晶圓工業'],4,'機器人產業與晶圓工業同屬高科技產業。')
ch('【素養】在位於日本北海道東北部的鄂霍次克海，每年 1～3 月都有機會可以欣賞到「流冰」，此一景致是因為洋流自緯度更高的地區，將半融化的海冰牽引至北海道的北方海面所形成的景觀。其洋流可能為何？',['黑潮主流','黑潮支流','親潮主流','中國沿岸流'],3,'由高緯度流向低緯度的洋流可以判斷應為寒流，故應為親潮。')
ch('「台積電與與日本 SONY、DENSO、Toyota 等企業成立了合資公司『JASM』，並於九州熊本地區設廠，帶動了該地區的發展。」文中提及的設廠地點在圖中的何地？',J,4,'熊本位於九州，即圖中丁。',img=P(18,3,460,55,712,315))
ch('【素養】日本是礦產原料不足的國家，各時期的經濟發展都需仰賴外界，故國際貿易可說是日本經濟命脈。該國國際貿易發達，與其地理環境哪一項特徵關係最密切？',['豐富的火山及溫泉景點','四季變化小的氣候環境','四面環海且曲折的海岸','廣大且平坦的平原地形'],3,'國際貿易需配合運輸，其中又以海運比重較高，所以需要有天然良港配合。')
psg('海拔 3,776 公尺的富士山是日本最高峰，也是日本的象徵，更是全球遊客登山人數最多的高山，圖為每月登山客人數的示意圖。')
ch('文中提及的景點位於日本哪一大島？',['本州','四國','九州','北海道'],1,'富士山位於本州。')
ch('日本富士山形成的原因，與下列何者關係密切？',['洋流系統','火山作用','侵蝕作用','河川沖積'],2,'日本位處環太平洋火山地震帶，火山活動活躍，富士山即為一座活火山。')
ch('依圖判斷，登山遊客人數最多的某兩個月分，其可以吸引眾多遊客的主要原因為何？',['可見到山道高聳的冰壁','此時為山頂融雪的季節','可同時欣賞雪景與楓紅','此時降水機率相對較小'],2,'7、8 月遊客數量多，因此時為夏季，山頂融雪，交通較方便與安全。',img=P(18,3,420,640,715,860))
endp()
psg('韓屋是韓國傳統建築，其最大特色是「溫突」的供暖設計，這樣的設計與中國北部的「暖炕」類似。朝鮮半島四季變化明顯，韓國人夏天生活在涼爽的過廳木板上，冬天住在有溫突設施的房間裡。近年來，愈來愈多的觀光客想要體驗這種傳統建築，其中在首都首爾附近的南山韓屋村及北村可以體驗傳統韓屋之美，而入住韓屋的遊客，通常會搭配極具在地特色的韓式料理。')
ch('【素養】韓屋中的「溫突」，也可以在中國哪一地區發現類似的設施？',['海南島','東南丘陵','黃土高原','珠江三角洲'],3,'文中說明溫突的供暖設計與中國北部的「暖炕」類似，出現在冬季氣溫較低的地區，故應為中國北部的黃土高原。')
ch('韓屋中需要此項供暖設計的主要原因為何？',['地勢崎嶇','緯度偏高','土壤貧瘠','缺乏木材'],2,'朝鮮半島因為緯度高，冬季氣溫低，故需要可以取暖的設施。')
ch('上文中說到南山韓屋村與北村，其地點應位於圖中何處附近？',J,3,'首爾靠近黃海附近，應為圖中的丙。',img=P(18,4,560,640,712,850))
ch('入住韓屋的遊客所體驗到的特色美食最可能為何？',['壽司','泡菜','蛋包飯','生魚片'],2,'泡菜為韓國特色美食。')
endp()

sec('第10回 歷史 第三篇第1章 商周至隋唐時期的國家與社會')
ch('【進階】周代的歷史演變如下列甲至丙的發展（甲：中央分封土地給大臣；乙：？；丙：諸侯勢力坐大），乙的「？」最可能為下列何者？',['因實施暴政使平民叛亂','外族侵略導致王室衰微','貴族聯合大臣殺害周王','王室推崇儒家遭到反彈'],2,'西周末年犬戎入侵，王室被迫東遷，此後王室衰微，諸侯勢力坐大。')
ch('小寶在圖書館看到圖的書籍（贏政傳），根據圖片內容判斷，此書裡所撰寫的人物重要歷史成就，可能為下列何者？',['滅亡秦帝國後，創立漢朝帝國','設立了皇帝制度，自稱始皇帝','統一胡人政權，設立科舉制度','改善察舉，採行九品官人之法'],2,'嬴政統一天下，以皇帝為君王的新稱號，自稱「始皇帝」。',img=P(19,1,610,820,770,1000))
ch('東周各國爭戰不休、兼併激烈，秦國統治者為求富國強兵而厲行變法，讓秦國奠下富裕強大的基礎，當時的變法項目包括下列哪一項？',['以中央官員評定士人，分為九品','依照宗法血緣的關係，授予爵位','授予貴族土地，掌握禮樂等權力','編列戶籍，使平民納稅和服勞役'],4,'商鞅變法編列戶籍，使平民納稅和服勞役。')
ch('圖是名秀正在看的漫畫內容（聽說政府要成立一間「太學」……只要在學校內表現優良，成績優異就可以任官），由圖中人物所述內容，可知是哪一位皇帝的政績？',['秦始皇','周武王','漢武帝','唐太宗'],3,'漢武帝設立太學，成績優異者可任官。',img=P(19,2,185,245,760,430))
ch('中國儒家思想的誕生是由當時政局混亂，加上知識不再為貴族所壟斷，百姓也可以受教育，因而出現各種學說。後來由於官方的支持，而使得儒家思想從何時才開始成為中國的主流思想？',['西周','東周','秦代','漢代'],4,'漢武帝獨尊儒術，儒家思想成為中國的主流思想。')
ch('遠古時期，中國境內從出現部落、部落聯盟，逐漸發展為國家。大約三千多年前，商、周兩個王朝先後形成，坐落於哪個流域？',['長江流域','黃河流域','淮河流域','珠江流域'],2,'商、周兩個王朝坐落於黃河流域。')
ch('【進階】西元前 221 年，秦滅六國後，統一天下。為使帝國長治久安，秦始皇遂實行中央集權，使國家一切事務全掌握在皇帝手中。此時政治制度的特色為下列何者？',['長官由地方推舉','經選舉產生官員','廢封建、行郡縣','分封宗室駐守各地'],3,'秦始皇廢封建，行郡縣，郡縣長官由中央直接任免。')
ch('下列哪一位君王自認自己的功業超越三皇五帝，創造「皇帝」取代「王」，以作為帝王的新稱號？',['周王','嬴政','商鞅','漢武帝'],2,'嬴政創造「皇帝」稱號，自稱始皇帝。')
ch('某大學舉辦了「科舉制度在臺灣」的研討會，根據統計，清代臺灣的進士曾達到 33 位，為此還邀請了臺灣最後一名進士汪春源的曾孫來臺進行交流。上述所提到的制度，最早應源自於中國哪一時代？',['秦','漢','隋','唐'],3,'科舉制度始於隋代。')
ch('秦朝滅六國而統一天下，曾經盛極一時，但後來竟只維持 15 年就亡國了，其主要原因為何？',['水災頻仍，瘟疫肆虐','統治嚴厲，民心劇變','幣制混亂，國家破產','外患嚴重，無力抵抗'],2,'秦朝統治嚴厲，民心思變，很快便滅亡。')
ch('【進階】在著名青銅器「毛公鼎」上，記載著周天子冊封其叔父毛公時的叮嚀：「希望你在掌理政務，要好好治理領地，對王室要忠心。」他們形成如此關係的原因為何？',['封建體制','部落聯盟','推舉孝廉','科舉制度'],1,'周代實施封建，周天子分封同姓宗室為諸侯。')
ch('魏晉南北朝世族代代高官厚祿，形成政治上的特權階級，而且這些世族通常是地方的領袖，在家鄉擁有大片土地莊園。而門第社會的形成，使得世族不願和地位不同的人交往、通婚，以維持自己的尊貴地位，這樣的現象，即使貴為皇帝之尊，也無法干預。造成上述現象的原因為何？',['採九品官人之法','採用科舉制度','封建下貴族世襲壟斷','全國推舉孝、廉人才'],1,'九品官人法使世族壟斷官位，形成門第社會。')
ch('【素養】中國古代某一時期的民間童謠：「舉秀才，不知書；舉孝廉，父別居；寒素清白濁如泥，高第良將怯如雞」。辛辣地諷刺了當時的社會狀況，反諷當局選拔的孝子不是孝子，推舉的廉吏非廉吏。該民謠最有可能出現在下列哪一時期？',['商代','周代','秦代','漢代'],4,'文中提到選拔「孝子」與推舉「廉吏」指的是漢代實施的察舉。')
ch('阿德是生活在東周時期的平民，根據判斷，他在當時很可能會有什麼樣的生活？',['有機會能接受教育','子女被推舉孝子，到中央任官','以通用的小篆與鄰國書信交流','接受中央指派，擔任郡縣長官'],1,'東周時期知識不再為貴族所壟斷，平民也有機會接受教育。')
ch('【進階】筱涵整理商周兩代的政治制度發展如下表，但是其中有一項「錯誤」，應為下列何者？',['商代：商王對其分封勢力的控制十分有限','西周：分封對象以血緣關係為基礎','西周：封建制度建立的社會階級相當鬆散','東周：周王室衰微，使封建體制逐漸瓦解'],3,'西周時代，封建體制日趨成熟，社會階級嚴明。')
ch('歷史老師藉由圖（皇帝、官僚、平民）解說中國某一制度所造成的社會階層現象，由此可知是下列哪一制度？',['郡縣','封建','宗法','科舉'],1,'郡縣制度下，皇帝透過官僚直接統治平民。',img=P(20,1,565,75,755,245))
ch('【進階】電視劇《皓鑭傳》以東周後期歷史為背景，劇中女主角趙姬李皓鑭，雖然晚景淒涼，被幽禁王宮老死，但是兒子成功登基，並且統一中國，結束東周以來的亂局？',['嬴政','商鞅','鄭經','漢武帝'],1,'秦王嬴政統一天下後，以「皇帝」為君王新稱號，成為中國第一個皇帝。')
ch('日治時期，臺灣總督府為了整頓臺灣的經濟，曾設立臺灣銀行，同時統一度量衡。而中國歷史上，最早在哪個朝代即有君王推行相似的政策？',['商代','周代','秦代','漢代'],3,'秦始皇統一貨幣、度量衡。')
ch('【素養】元宵節將近，歷史老師以猜燈謎方式幫同學複習課本知識，圖為真真選到的燈謎題目（主題：？；秦朝、隋朝）。可知答案為何？',['統一文字，整合社會','士族勢力的形成與沒落','終結亂世，統一天下','封建制度的興衰過程'],3,'秦朝終結春秋戰國時代，隋朝終結南北朝時代。',img=P(20,1,545,685,760,785))
ch('【素養】電視劇「大秦」以東周後期為歷史背景，呈現秦國由弱轉強的過程。為符合史實，下列何者「不應該」出現在此劇中？',['商鞅變法成功，奠定富強基礎','政府將人民編入戶籍嚴加管理','秦國掌握政權並落實封建體制','秦王嬴政攻滅六國後統一天下'],3,'東周後期各國國君抑制貴族勢力，封建體制逐漸瓦解。')
ch('娜娜上完歷史課之後，統整了西周與東周的政治、文化、經濟與社會等各方面的比較，下列有關於娜娜所統整的重點敘述，何者有誤？',['西周的封建社會制度，社會階級相當嚴謹','東周前期，諸侯勢力坐大，封建體制鬆動','西周的封建制度的實施與土地的分封有關','東周體制中，平民仍然無法任官參與政治'],4,'東周時期平民接受教育的機會大增，也可任官參與政治。')
ch('【素養】秦始皇與漢武帝是中國歷史上赫赫有名的君王，後世並稱為「秦皇漢武」，下列關於兩位君王的政績，何者正確？',['秦始皇以宗法血緣治國','秦始皇用察舉選拔官員','漢武帝建太學培養人才','漢武帝首度實施郡縣制'],3,'(A)西周以宗法血緣的關係，強化統治(B)漢武帝增設「察舉」選才辦法(D)秦始皇首度實施郡縣制。')
ch('【素養】圖為中國歷史上某種官方文件的內容（建初十二年正月登錄戶籍），根據圖中內容判斷，當時政府製作此官方文件的主要目的最可能為下列何者？',['配合科舉選拔人才，促進社會的流動','設立太學教授儒學，優秀者得任官職','推行封建制度並保障貴族世襲的權力','掌握人力作為徵集賦稅和勞役的依據'],4,'秦國在商鞅變法後，為了提高徵收賦稅和分派勞役，將人民編列戶籍，加強對人民的控制，故選(D)。',img=P(20,2,410,535,762,900))
ch('西周的統治基礎，是透過各種制度維繫，其中透過血緣的親疏建立尊卑關係，以強化對諸侯的統治，是下列哪一制度？',['封建制度','郡縣制度','科舉制度','中央集權制度'],1,'周天子利用「宗法」血緣關係，強化對諸侯的統治。')
psg('中國的某時期，天子缺乏威望而使王室衰微、諸侯坐大，當時政局紛亂，原本的封建秩序瓦解，諸多貴族流落民間為了謀生，開啟了私人講學風氣，該時期有許多學者紛紛提出不同的治國理念。在各種學派蓬勃發展下，當中最著名的，分別是主張仁政的儒家、主張依循自然不干涉人民生活的道家、及支持嚴刑峻法的法家。雖然政局紛亂，但因貴族流落民間，使得平民接受教育的機會大增，也可上位任官參與政治。')
ch('文中描述的時代，其任官特色應為下列何者？',['自行報名參加考試，考取者任官職','經由地方郡縣定期向中央推舉廉吏','接受中央選任官員評定被選拔任官','各國統治者為追求富強而用人唯才'],4,'東周時期各國統治者為追求富強而用人唯才。')
ch('文中提及的制序之所以瓦解，應與下列何者有關？',['外族入侵，導致王室東遷','實施大型工程使人民反抗','君主年幼引發官員想奪權','連年饑荒，導致經濟衰退'],1,'東周之前的西周之所以封建瓦解，與外族犬戎入侵有關，故選(A)。')
ch('阿偉是生活在該時代的官員，有機會與商鞅一同工作，他可能會受命執行哪一政策？',['厲行法治並編列戶籍控制人民','率軍抵抗犬戎以保衛西周王室','設置太學由中央選拔優秀人才','制定禮法要求各階級嚴格遵守'],1,'商鞅變法厲行法治，並編列戶籍控制人民。')
ch('關於文中提及的儒家，下列何者為主要的代表？',['秦始皇','商鞅','孔子','周王'],3,'孔子為儒家的代表人物。')
endp()
psg('中國在中央集權政體形成後，人才選拔是帝國維繫政權的重要措施之一。（甲）科舉制度、（乙）推舉孝廉、（丙）九品官人之法，這三者都是歷代曾實施的選才制度。')
ch('根據上文，（甲）使平民入仕機會逐漸增加，提升社會階層的流動性，亦是較客觀的選才方式。此制度自哪一個朝代開始實施？',['西漢','曹魏','隋代','唐代'],3,'科舉制度始於隋代。')
ch('根據上文，（丙）制度常被詬病會有「上品無寒門（平民），下品無世族」的現象。造成此種現象的原因為何？',['寒門無法負擔考試費用，不能參加人才評選','世族比較具備儒家的孝子、廉吏等道德標準','評選重視家世背景，世族子弟擁有任官優勢','皇帝畏懼世族權力，規定上品一定選擇世族'],3,'九品官人法評選重視家世背景，世族子弟擁有任官優勢。')
ch('【進階】根據上文，這三項選才制度在歷史上實施的先後順序，應為下列何者？',['甲乙丙','乙丙甲','丙甲乙','乙甲丙'],2,'（甲）科舉制度──隋唐、（乙）推舉孝廉──漢代、（丙）九品官人之法──曹魏。')
endp()

sec('第11回 歷史 第三篇第2章 商周至隋唐時期的民族與文化')
ch('自古以來漢民族就不斷與周遭民族發生衝突，因此許多朝代對於外族皆有夷夏之別的觀念，但到了中國某個時期的君王對外族採取較開放、平等的態度。甚至有皇帝曾說過：「自古帝王皆貴中華，賤夷狄，朕獨愛之如一，故其種落皆視朕如父母。」可知這位皇帝最有可能是處於下列哪一個時期？',['隋唐時期','秦漢時期','魏晉南北朝時期','商周時期'],1,'唐太宗對外族採取開放、平等的態度。')
ch('阿倫是生活在中國某時代的居民，他聽聞皇帝派遣使者出使西域，聯絡西域各國攻打匈奴。根據內容判斷，阿倫生處的朝代最可能為下列何者？',['西周','秦','漢','魏晉南北朝'],3,'漢武帝派張騫出使西域，聯絡西域各國攻打匈奴。')
ch('在古羅馬時期，絲綢的價值相當於等重的黃金，古羅馬人以能穿上中國絲綢為榮。中國的絲綢能通過絲綢之路傳到歐洲，與下列哪一事件有關？',['玄奘西行取經','秦王統一六國','張騫出使西域','商鞅實行變法'],3,'張騫出使西域，開啟絲綢之路。')
ch('新聞報導：「新疆的維吾爾族穆斯林，被強制學習官方宣傳並放棄伊斯蘭教信仰的一些重要內容。」上述提及的宗教是在中國哪一朝代時期傳入的？',['漢代','唐代','隋代','北魏'],2,'伊斯蘭教於唐代傳入中國。')
ch('魏晉南北朝時期，草原民族雖以武力紛紛入主中原，在文化上卻多能吸收漢文化，加速胡漢的融合，其中以下哪一民族的漢化政策最為積極？',['匈奴','鮮卑','突厥','吐蕃'],2,'鮮卑族建立的北魏，孝文帝積極推行漢化政策。')
ch('【進階】魏晉南北朝時期，佛教廣為流傳，信徒快速增加，下列何者「不是」造成這種現象的原因？',['君王的積極提倡','佛經的大量翻譯','人民飽受戰亂之苦','玄奘前往印度取經'],4,'玄奘是唐代人。')
ch('【進階】中國經濟發展的重心原在黃河流域，東漢末年因陷入混亂，人口開始逐漸遷移，大規模的人口遷移始於西晉末年。此時人口大規模的遷移方向為何？',['由南向北','由北向南','由東向西','由西向東'],2,'中國經濟發展的重心原在黃河流域，魏晉南北朝後，北方長期戰亂，大批人士遷往南方。')
ch('【進階】聞名世界的古建築「萬里長城」，乃是連結戰國時期三個國家所築的長城。當時修築的主要目的為何？',['避免人民叛逃北方','建立明確國家邊界','防禦北方草原民族','阻擋北風侵害農作'],3,'當時修長城是防禦北方的匈奴。')
ch('魏晉南北朝時期，於北方建國的胡族當中，以「甲族」建立的政權勢力最盛，其推動了漢化政策，對胡漢融合有關鍵性的作用。後來的隋唐帝國，即是承繼了這支民族的文化，而締造出輝煌的盛世。上文中的「甲族」為何？',['匈奴','吐蕃','突厥','鮮卑'],4,'鮮卑君主北魏孝文帝實施漢化政策，加速胡漢文化交流。')
ch('「文皇南面坐，夷狄千群趨。……獻號天可汗，以覆我國都。」文中以天可汗稱唐太宗，是因為其擊滅哪一外族，使西北各族紛紛歸順並獻上此尊號？',['匈奴','鮮卑','東突厥','吐蕃'],3,'唐太宗擊滅東突厥，西北各族尊稱其為「天可汗」。')
ch('當日劇及日本流行文化進入臺灣時，其親近感，乃是因文化而來，其便捷度，更因文字中的漢字相似。追本溯源，最主要是因為唐化運動顯著，而這股唐化運動歷史上稱為何者？',['大化革新','明治維新','商鞅變法','胡漢融合'],1,'日本仿效唐朝進行改革，稱為「大化革新」。')
ch('【進階】魏晉至隋唐時期，西域的繪畫、雕刻和建築藝術傳入中國，對石窟文化產生深遠影響。有關上述的石窟文化發展，下列何者最可能是重要的媒介？',['文成公主和親時引入','西北各族君長的歸順','征伐大食而引進文物','隨著佛教的傳入興盛'],4,'魏晉南北朝至隋唐時期，中國的佛教興盛，石窟的佛像造型深受外來文化影響。')
ch('阿德在觀看歷史戲劇時，看到了圖的對話（沒想到才一眨眼，首都洛陽城就被胡人占據了。聽說官員和許多人都逃到南方，新皇帝也在……）。根據內容判斷，該事件發生的時間，應該為哪個時期？',['秦末','西漢','西晉','唐'],3,'根據洛陽遭胡人入侵、漢人南遷判斷，應為西晉末年的永嘉之禍。',img=P(21,4,440,200,712,385))
ch('王國維的《讀史》詩：「南海商船來大食，西京祆寺建波斯，遠人盡有如歸樂，此是唐家全盛時。」此詩對唐代的繁榮開放有很好的寫照，詩中的「大食」是指來自何地的商船？',['日本','新羅','羅馬帝國','阿拉伯帝國'],4,'「大食」為唐代對阿拉伯帝國的稱呼。')
ch('【進階】小美是位虔誠的佛教徒，她找了一些有關佛教在中國起源與發展的資料，不小心寫錯了哪一項？',['佛教起源於新羅，唐代時由使節傳入','佛教約於 1 世紀前後經西域傳入中國','魏晉南北朝時期，多位帝王提倡佛教','玄奘翻譯佛經，對佛教發展貢獻很大'],1,'佛教起源於印度，漢代時傳入中國。')
ch('【素養】圖為佳佳在上歷史課時，看到的某國文字。他想起老師曾經提過這個國家的文字與中文的關係密切，與當時派遣留學生前往中國學習有關。根據上述內容判斷，下列何者正確？',['該國文字完全模仿中國文字而成','該國因將佛教傳入中國加深交流','該國地理位置為今日的朝鮮半島','該國後來的改革稱之為大化革新'],4,'圖中的文字為片假名和平假名，是日本改良中國的漢字而成，該國後來展開唐化運動，稱為「大化革新」。',img=P(21,4,535,860,718,995))
ch('北方草原民族雄據中原地區，他們在武力上雖然是勝利者，但是在文化上卻被漢族所同化。其中以哪一位皇帝最能接受中原文化，並且積極展開大規模的漢化運動？',['秦始皇','漢武帝','唐太宗','北魏孝文帝'],4,'北魏孝文帝積極推行漢化運動。')
ch('【素養】日本、新羅與吐蕃都曾受到中國文化的影響，進而發展出自己的文化特色，下列相關敘述何者正確？',['三地都曾被唐代納入版圖直接統治','新羅和日本的文字均受到漢字影響','因地理因素，吐蕃與新羅互動密切','文成公主嫁到日本而帶來中國文化'],2,'(A)均未被唐代直接統治(C)日本與新羅同屬東亞文化圈(D)文成公主嫁到吐蕃。')
ch('2019 年日本明仁天皇退位，德仁天皇繼位，以「令和」為年號取代前任天皇的「平成」年號。這種模仿中國皇帝使用年號紀元的方式，與下列何者最相關？',['漢代公主和親日本後，帶動日本漢化','唐朝派遣留學生赴日，宣揚文化制度','7 世紀推動大化革新，學習唐代制度','19 世紀為治理臺灣，汲取中華文化'],3,'日本於 7 世紀推動大化革新，學習唐代制度。')
ch('唐太宗以戰爭和外交建立世界性的帝國，被尊為「天可汗」，並成為東亞國際盟主。從此東亞以唐帝國為中心逐漸形成「東亞文化圈」，其中包括下列何者？',['天竺','大秦','日本','大食'],3,'東亞文化圈包括日本、新羅等地。')
ch('【素養】歷史老師請同學以分組方式介紹一本歷史書籍，品萱他們所選擇的書籍為《從平城到洛陽》。可知他們的報告內容與哪一歷史事件有關？',['匈奴南侵，胡漢攻防','開通西域，東西相遇','胡漢融合，文化交流','唐化運動，東亞共榮'],3,'北魏孝文帝致力於胡漢融合，將首都由平城遷到洛陽。')
ch('【進階】旅遊雜誌介紹：「在中亞的撒馬爾罕，你必須嘗試撒馬爾罕麵包和看看撒馬爾罕紙。你無法在世界其他地方看到，這是中東第一個造紙的地方。」造紙原是中國的發明，該地之所以也有造紙的原因為何？',['張騫通西域後，最早把紙賣到該地','當地政府遣使來大唐帝國學習造紙','唐朝高僧赴當地取經，並傳授造紙術','怛羅斯之役，中國士兵被俘技術外流'],4,'唐代時，唐朝軍隊與大食交戰於中亞的怛羅斯，促成中國造紙術西傳。')
ch('阿騰看到一則報導：「2024 年，疫情後再次於中國長城舉辦馬拉松競賽。由於地形的起伏，加上古蹟的影響，增加了競賽的挑戰性，吸引各國選手的競逐。」如果阿騰想要了解上述比賽場地的歷史發展，最早可以從哪一時代加以研究？',['西周','東周','秦','漢'],2,'長城最早是東周戰國時期各國所修築。')
ch('【素養】魏晉南北朝時期，胡漢接觸頻繁，下列關於此一時期的特徵，何者敘述「錯誤」？',['奠定日後經濟重心南移的基礎','儒家思想從此成為學術的主流','北方草原民族紛紛在中原建國','世家大族掌控政治經濟的權力'],2,'儒家思想成為學術的主流是在漢武帝時。')
psg('圖的詩（太平若為將軍定，紅顏何須苦邊疆，天若有情天亦老，解憂無奈歷滄桑。）出自漢朝嫁到西域烏孫的解憂公主之手，意思是將士們若能在戰場上獲勝，何須金枝玉葉的公主嫁到異鄉受苦，道出和親公主的萬般無奈。所謂和親是指以公主或宗室女子下嫁的方式換取和平，是一種以弱制強的外交政策。')
ch('上文中所提及之「西域」通常是指何處以西之地？',['山海關','虎牢關','玉門關','雁門關'],3,'西域通常指玉門關、陽關以西之地。')
ch('【進階】漢武帝年間，烏孫在西域中是強盛的國家，又與匈奴鄰近，因經營西域頗受漢武帝重視的（甲）曾上奏曰：「以厚禮招待，令他們（烏孫）向東移居，並許嫁公主，雙方結為兄弟之邦，共同制伏匈奴。」文中的（甲）應是下列何人？',['張騫','玄奘','商鞅','蔡倫'],1,'張騫通西域的最初目的是連絡西域各國攻打匈奴。')
ch('漢代對西域的經營除了達到牽制匈奴的效果，更促進絲路的開通。當時這條中西貿易的路線起於長安，經敦煌、西域後，最遠可達下列何處？',['大食','大秦','安息','大月氏'],2,'絲路最遠可達大秦（羅馬帝國）。')
endp()
psg('小豪參加了一場歷史解謎的活動，他看到的資料如下：\n資料一：869 年，一位 12 歲，來自「甲國」的的崔致遠奉命到中國首都長安學習儒家經典，希望可藉此於中國任官就職。六年後他成功考取任官資格，並於 28 歲時歸國。因當時的甲國積極模仿中國漢字、曆法，被稱為君子國，所以崔致遠在中國的經歷使他受到重用。\n資料二：中國當時的統治者因有部分胡人血統，對於外族的接納度較高。當時任用不少胡人官員，武將也多用胡人，著名人物如安祿山、史思明。')
ch('資料一當中的「甲國」，最可能為下列何者？',['日本','吐蕃','天竺','新羅'],4,'崔致遠為新羅人。')
ch('【素養】根據資料二判斷，若生活在當時的胡人，很可能會有什麼樣的生活？',['跟著士兵與大食國進行交戰','造訪與匈奴和親的文成公主','聽聞使者張騫即將前往西域','漢化政策下改漢姓及著漢服'],1,'唐帝國曾與大食交戰於怛羅斯，故選(A)。')
ch('【進階】根據文中內容判斷，小豪參加的解謎活動主題應為下列何者？',['東周文化以及儒家經典的形成','秦帝國統一後中國文字的傳播','漢代古絲路與西域族群的互動','唐帝國風情與世界一家的特色'],4,'根據資料中的首都長安有來自外國的留學生、胡人任官的狀況判斷，應為唐帝國特色。')
ch('若依照資料一、二的時代背景判斷，最可能還會出現哪一方面的試題？',['草原民族匈奴崛起','始皇兵馬俑的由來','伊斯蘭教傳入中國','儒家的創立與主張'],3,'資料一、二背景均為唐代，伊斯蘭教在唐代時經由西域傳入中國。(A)(D)東周(B)秦代。')
endp()

sec('第12回 歷史 第三篇1～2章 複習')
ch('【進階】小明上課時，不小心抄錯老師講解封建制度的重點。下列筆記中何者有誤？',['商代屬於封建體制的發展階段','西周時期，封建社會階級嚴明','封建體制下，平民仍可享有禮樂教化','封建制度中各級貴族身分都是世襲的'],3,'(C)被貴族掌握，平民與奴隸無法享有。')
ch('中國的皇帝制度延續了二千多年，此制度正式確立是由哪一個朝代開始？',['商','西周','東周','秦'],4,'秦始皇創立皇帝制度。')
ch('在此以前的中國，只是一種封建的統一。直到此時，中央才有一個更正式的統一政府，其所轄各地方，不再是封建性的諸侯列國並存，而是緊密隸屬於中央的郡縣體制行政區。上述的「此時」最可能是指下列哪一朝代？',['商','周','秦','漢'],3,'秦廢封建、行郡縣。')
ch('凱耀所生活的年代，由於整個社會氛圍提倡「經學傳家、累世當官」，所以凱耀從小就在父親的教導之下熟讀經書，期許有一天可以因此任官。凱耀最有可能生活在哪一個朝代？',['周朝','秦朝','漢朝','隋朝'],3,'漢代以經學取士逐漸形成「經學傳家、累世當官」的世家大族。')
ch('【進階】阿鴻整理了北魏孝文帝的相關內容如附表（族群：鮮卑族；遷都：平城→洛陽；政策：說漢語改漢姓；成就：滅東突厥）。但老師提出，他整理的內容中有一個「錯誤」，根據表格內容判斷，應為下列何者？',['族群','遷都','漢化內容','外交成就'],4,'(D)為唐太宗的施政。',img=P(23,2,515,225,770,370))
ch('每個時代都有該時代的特色與氛圍，中國某個時期因為任官選才的方式有所偏頗，而形成「上品無寒門，下品無世族」的現象。上述現象會出現在下列何時？',['商朝時期','西周時期','隋唐時期','曹魏時期'],4,'曹魏實施九品官人法，形成「上品無寒門，下品無世族」的現象。')
ch('中國早期對西域各國的認識十分貧乏，至張騫通西域後才對西域實際情況有所了解，古代對西域的研究材料主要亦是出自張騫所得到的資料。張騫出使西域的行動始於哪一位君主？',['秦始皇','漢武帝','北魏孝文帝','唐太宗'],2,'漢武帝派張騫出使西域。')
ch('【進階】中國歷史上，漢人本來多在北方發展，第一次漢人大規模向南方遷徙，在南方建立新政權，並增進長江流域的開發，是在下列哪一事件後？',['犬戎入侵使周王室東遷','秦王兼併各國統一天下','胡族進攻西晉首都洛陽','唐帝國成為東亞的盟主'],3,'西晉爆發永嘉之禍，北方戰亂使漢人隨晉室南遷。')
ch('漢武帝對內政策上，用人唯才，不問出身，規定全國每年推舉人才，凡是被推舉的人，在地方上必須有良好的名聲，而且要具備儒家的學術基礎，以致該時期培養出大量名臣良將。此制度為何？',['禮樂制度','宗法制度','推舉孝廉','科舉制度'],3,'漢武帝實施察舉，推舉孝廉。')
ch('唐代是中國歷史上輝煌燦爛的時代，在社會生活、文學藝術等各個方面所呈現出來的繁盛景象，被後世稱為「盛唐氣象」，其中文化外傳更是影響深遠。某國因全力模仿中國的漢字、曆法，而有「君子國」之稱，該國為下列何者？',['天竺','新羅','日本','高麗'],2,'新羅模仿中國漢字、曆法，有「君子國」之稱。')
ch('【進階】唐朝有首詩的部分內容寫道：「舊時王謝堂前燕，飛入尋常百姓家。」類似王、謝這些世家大族的沒落，除因政治動亂外，又與下列哪一項制度的實施有關？',['科舉制度','孝廉選官','封建體制','九品官人之法'],1,'隋代為抑制世族勢力，廢除九品官人之法，改行科舉。')
ch('【素養】莉莉在觀看戲劇時看到了兩位古代官員的閒聊如下（甲：「聽說之前外族入侵，但諸侯們都沒有協助支援，導致國君遭到殺害。」乙：「新任的國君跑到東方重新建國，結果諸侯們也不再聽從王室的話，各自為政。」），其中提及的「外族」應為下列何者？',['鮮卑','犬戎','匈奴','大秦'],2,'根據判斷，上述背景應為西周封建制度的瓦解與衰敗，與犬戎的侵略有關。')
ch('唐太宗時聲威大振，西北各族的部落君長稱他為「天可汗」，這是由於唐太宗時平定哪一外患？',['匈奴','大食','西突厥','東突厥'],4,'唐太宗平定東突厥。')
ch('【進階】圖是老師在黑板上寫的人物（漢武帝、北魏孝文帝），請同學根據內容判斷，回答與其相關的影響，下列何人回答正確？',['經濟貿易的發展','科技工藝的成就','帶動社會的改革','外來宗教的傳布'],3,'漢武帝增設察舉選才、設立太學；北魏孝文帝採取漢化政策，均改變了當時的社會。',img=P(23,4,480,610,712,730))
ch('【素養】阿甘正在臺上報告歷史作業，他的主題是「唐代社會文化」。下列哪一敘述是阿甘報告會提到的內容？',['社會階層嚴謹，王室藉由宗法血緣強化統治權力','政府濫用民力築長城，導致民怨四起，揭竿起義','將首都由平城南遷到洛陽，加速胡漢間文化交流','首都內有許多漢人都穿戴胡帽，與胡人來往頻繁'],4,'(A)為西周時代(B)為秦代(C)為北魏。')
ch('元代高明在《琵琶記》中說：「十年寒窗無人問，一舉成名天下知。」這句話反映的社會現象，最早出現於中國哪一時期？',['秦朝','漢朝','西晉','隋朝'],4,'這句話是指士人長期閉門苦讀，一旦在科舉考試中成功，就能聞名天下。科舉考試最早出現在隋朝，故選(D)。')
ch('【素養】小夏正在統整歷史筆記，下表為他統整中國歷代漢人政權所面對的主要草原民族（秦代：匈奴；漢代：鮮卑；西晉：北方胡人；唐代初期：突厥）。可知小夏何處整理「有誤」？',['秦代','漢代','西晉','唐代初期'],2,'漢代的外患主要為匈奴。',img=P(24,1,185,375,762,485))
ch('【素養】唐代在全盛時期於文化、政治、經濟、外交等方面達到很高的成就，對周邊國家產生很大的影響。下列與此相關的敘述，何者正確？',['與吐蕃交戰於中亞，使造紙術西傳','唐派遣使節遠赴日本，使文化外傳','朝鮮半島上漢化最深的國家是新羅','與大食透過和親方式促進文化交流'],3,'(A)大食(B)日本派遣使節赴中國學習(D)唐以文成公主和親吐蕃。')
ch('絲路的開通為漢代的中西文化交流奠下基礎，圖（起點→河西走廊→蔥嶺（今新疆地區）→西亞→終點）中的起點及終點應分別填入下列何者？',['長安、大食','長安、大秦','洛陽、大食','洛陽、大秦'],2,'絲路起於長安，最遠可達大秦。',img=P(24,1,185,970,700,1040))
ch('李祥是中國東晉時期的一名士人，若他想求取官職，應該以哪種方式入仕？',['經由九品官人之法成為了官吏','繼承身為貴族的父親爵位受封','經地方長官推舉為孝子或廉吏','參加科舉考試以學問求取功名'],1,'魏晉南北朝時期實施九品官人之法。')
ch('【素養】花花在閱讀某部歷史書籍的內容如下：「西元 4 世紀初期，中國政權正值大規模變動。漢人剛喪失黃河流域的統治權遷至南方，而北方胡人崛起，在黃河流域建立政權，此後也讓中國進入長時期的南北分裂。」根據上述內容判斷，下列何者正確？',['漢人在南方建立的政權應為東晉','漢人南遷的背景應為犬戎的侵略','漢人因平城遭胡人占領遷都至洛陽','漢人勝利後實行封建制度維繫政權'],1,'由「漢人將黃河統治權遷移至南方，北方由胡人占領」判斷，應為西晉末年至東晉建國的永嘉之禍，故選(A)。')
ch('【進階】假如你是一名穿越時空來到漢代採訪漢武帝的記者，下列何者最有可能是漢武帝的採訪內容？',['推崇儒家思想，建立選拔人才辦法','首度以「皇帝」作為君王的新稱號','用科舉制度作為選任官員方式','統一文字、貨幣、車軌是創舉'],1,'(B)(D)是秦始皇(C)是推舉孝廉。')
ch('【素養】由中國主辦的國際賽事「商學院戈壁挑戰賽」，至今已十幾屆，臺灣也有多位學員參賽，挑戰 1300 多年前玄奘大師取經、史稱「八百里流沙」的戈壁路程。該競賽特別紀念這位歷史人物的原因為何？',['玄奘是最早把佛教傳入中國的僧侶','玄奘是魏晉南北朝佛教盛行的關鍵','玄奘是首位在中國傳教的印度僧侶','玄奘翻譯佛經促使唐代佛教中國化'],4,'(A)佛教在西漢末年傳入中國(B)(C)玄奘是唐代人。')
ch('阿雪在博物館參觀時，看到了某項文物的介紹如下：「在當時，青銅器不只是精美的藝術品，也是貴族才可以擁有的東西。有時貴族使用青銅器祭祀，又被稱為『禮器』。禮樂規範貴族的生活，突顯身分和階級的嚴謹和不可隨意撼動的地位。」上述文物製作背景，最可能與哪一制度有關？',['郡縣制度','封建制度','察舉','九品官人之法'],2,'文中描述的青銅器，應為商周時期實行封建制度下規範禮樂身分的文物，故選(B)。')
psg('下列是一首歌詞，描述一位歷史人物〇〇的故事：\n……布達拉宮，穿越來世情感。浩蕩的車帳，正給誰做嫁妝，熱鬧地奏響，把孤單埋葬。大唐的輝煌，□□的蠻荒。……征戰的年代，〇〇和松贊，心相印的情感，攜手長相伴，千年不悔，高原是故鄉。')
ch('歌詞描述歷史人物〇〇隨著浩蕩的車帳前往異邦，從此高原成了故鄉。這位歷史人物為何人？',['商鞅丞相','張騫使節','玄奘法師','文成公主'],4,'文成公主嫁給吐蕃的松贊干布。')
ch('由上述的歌詞判斷，該位歷史人物遠赴異邦，應是在哪一位皇帝在位時？',['秦始皇','漢武帝','唐太宗','北魏孝文帝'],3,'文成公主於唐太宗時和親吐蕃。')
ch('歌詞中的□□雖然蠻荒，卻也成了這位歷史人物最後的歸屬與故鄉。上述□□指的是下列何地？',['新羅','吐蕃','印度','大食'],2,'文成公主和親吐蕃。')
endp()
psg('歷史劇《大佛開眼》的故事內容，為日本政治家吉備真備的奮鬥過程。當時的日本政局正逢不同以往的變化，社會氛圍以積極和西方大國唐國學習交流為中心，吉備真備在機緣下於 717 年前往交流，在當時的首都學習儒學、律令、禮儀等等，歸國之後得到天皇的賞識。當時的天皇致力推廣佛教，使佛教在日本社會中大為發展。這當中的變化，也與吉備真備等人與唐國的交流有不少關聯。')
ch('根據文中內容判斷，吉備真備前往的首都應為下列何者？',['咸陽','洛陽','長安','平城'],3,'唐代首都為長安。')
ch('吉備真備在唐國生活時，較「不可能」會有下列何種遭遇？',['欣賞來自西域的舞蹈','與友人討論科舉題目','與商鞅進行變法交流','旅遊時與穆斯林交談'],3,'商鞅為東周戰國時期秦國人。')
ch('【進階】有關文中提到在日本發展的宗教，其傳播發展下列敘述何者正確？',['為中國本土發展的宗教','漢代時期由吐蕃所傳入','唐初玄奘曾大量翻譯佛經','只有皇族信仰平民未接觸'],3,'佛教起源於印度，漢代自西域傳入中國，並於魏晉時期成為人民精神寄託。唐代玄奘翻譯大量佛經廣為流傳，故選(C)。')
ch('有關文中提及日本政局面臨不同以往的變化，最可能為下列何者？',['與唐軍交戰勝利後學得造紙技術','以天皇為中心成為中央集權國家','完全模仿中國的文字在日本流傳','受文成公主影響推廣農業的發展'],2,'日本當時推動大化革新，以天皇為中心，參考唐代制度成為中央集權國家，故選(B)。')
endp()

sec('第13回 歷史 第三篇第3章 宋元多民族並立的時期')
ch('【進階】小櫻利用圖示學習宋代的歷史。下列四幅小櫻繪製的兩宋與遼、西夏、金對立形勢簡圖，何者「有誤」？（選項見圖）',G,3,'(C)遼在北宋後期被金所滅，不與南宋並立。',img=P(25,1,185,600,600,915))
ch('「北宋末年，由女真族建立的一個王朝，女真族首領完顏阿骨打在統一女真諸部後，建都立國。」上述指的是哪一個政權？',['西夏','大理','遼','金'],4,'女真族建立金。')
ch('圖為張擇端的畫作「清明上河圖」，描繪北宋首都的繁榮，此場景貿易興盛的原因是因不再受何種政策的限制？',['郡縣制度','廣設驛站','坊市制度','實施科舉'],3,'宋代打破坊市制度的限制，商業活動不再受時間與地點限制。',img=P(25,2,230,30,655,280))
ch('【進階】阿德是生活在北宋時期的商人，根據判斷，他很可能會有什麼樣的生活？',['透過活字印刷術印製大量書籍販賣','為了準備科舉而研讀《四書集注》','前往驛站與外國商人進行商業買賣','聽聞蒙古軍在邊境與軍隊爆發衝突'],1,'北宋時期畢昇發明活字印刷術，故選(A)。(B)(C)元朝(D)蒙古崛起於南宋。')
ch('「元」是中國第一個以異族統一天下的朝代，其版圖遼闊，但是立足中原卻不到百年就滅亡了。下列何者「不是」其衰亡的原因？',['民變紛起','財政混亂','重文輕武','帝位繼承紛爭不斷'],3,'重文輕武為宋代的國策。')
ch('【進階】部分史家認為，宋代並非如此積弱不振，而是他們遭遇的外患實力太過強大。北宋的主要外患「不包括」下列哪一部族？',['西夏','蒙古','契丹','女真'],2,'北宋的外患為金、西夏、遼。')
ch('文鍾是某個朝代的讀書人，居住在福建一帶。今年是他第一次參加科舉考試，但是受於當朝實施某種政策，導致考試題目較難、錄取率低；就算考上，也很難升遷到較高的職務。可知上述的政策為下列何者？',['推舉孝廉的任官標準','偏重文人的基本國策','宗法血緣的禮樂制度','差別待遇的種族政策'],4,'元朝實施差別待遇的種族政策，漢人與南人在法律、科舉等方面，受到不平等待遇。')
ch('南宋某學者集理學之大成，學術成就「致廣大，盡精微，綜羅百代」，被譽為繼孔孟之後影響最深遠的一代宗師，該學者是下列何人？',['畢昇','岳飛','朱熹','張擇端'],3,'朱熹集理學之大成。')
ch('宋代農業發展的重要關鍵，是新稻種的引進，加上耕作技術的改良，使得糧食產量大增。當時是由何處引進「早熟稻」？',['天竺（印度）','占城（越南）','大食（阿拉伯）','呂宋（菲律賓）'],2,'宋代自占城引進早熟稻。')
ch('「長城自古以來是中國抵禦北方草原民族的重要防線，但在宋代建國以前，卻因『燕雲十六州』被割讓給外族，長城失去防禦功能，使得宋代備受威脅。」此一外族為下列何族？',['契丹','突厥','女真','蒙古'],1,'燕雲十六州被割讓給契丹（遼）。')
ch('翔翔在暑假時與家人一同去旅遊，看到了某個古蹟的介紹如下（唐帝國時期，由當時來華穆斯林所建立。為目前中國保存最古老與完整的伊斯蘭教聖跡之地。該地港口同時為宋朝時的市舶司設立地點，因此充斥著豐富的歷史氛圍）。根據內容判斷，翔翔旅遊的地點最可能為下列何者？',['長安','汴京','泉州','洛陽'],3,'泉州為宋朝設立市舶司的港口。')
ch('【進階】宋代積弱不振，自建國後，即不斷遭受來自外族的威脅，最後並為其所滅。北宋和南宋分別亡於哪一外族？',['西夏、女真','契丹、女真','契丹、蒙古','女真、蒙古'],4,'北宋亡於女真，南宋亡於蒙古。')
ch('蒙古以草原民族入主中國，憑藉的是強盛的武力。統一全國後，元帝國唯恐漢人不服，遂施行高壓的統治方式，因蒙古人自身文化水平較低，鑑於漢族傳統士人地位高、影響大，難以管理，便加以打擊。實施的種族政策以哪些等級受到較多的不平等待遇？',['蒙古人、色目人','色目人、漢人','漢人、南人','蒙古人、南人'],3,'元朝的種族政策中，漢人與南人受到較多的不平等待遇。')
ch('【進階】真真整理歷史筆記，其中一個地方卻不小心遭到汙損（11 世紀中期，於今日河南的三峰山爆發戰爭，當時＿＿族以少量的軍隊打敗了北方的金國。此事件之後，也讓金國從此一蹶不振，再也無法強大，最終滅亡）。根據內容判斷，該民族應為下列何者？',['女真','蒙古','契丹','突厥'],2,'金國最後遭到蒙古滅亡，故選(B)。')
ch('【素養】1206 年，一個位於漠北的草原民族，建立起龐大的帝國，並開始向外擴張，先後攻滅西夏、金等國，下列關於這個民族的敘述，何者正確？',['與北宋簽訂澶淵之盟維持和平','北宋時成吉思汗建立蒙古帝國','統一中國後將人民分為四等級','曾建立橫跨歐、亞、非的帝國'],3,'(A)與北宋簽訂澶淵之盟的是遼(B)南宋時(D)疆域僅跨歐、亞兩洲。')
ch('范仲淹有「先天下之憂而憂，後天下之樂而樂」的志向，可看出宋代文人自我期許相當高，往往「以天下為己任」，所以他們通曉經典是為了學以致用，而這也是宋代理學最基本的精神。宋代的理學最主要融合了哪些思想？',['儒學、佛學','儒學、伊斯蘭文化','儒學、科學','儒學、歐洲文化'],1,'宋代儒家學者融合佛學等思想，形成「理學」。')
ch('【素養】元代時，義大利人馬可波羅來到中國，他可能經歷下列何種狀況？',['在首都汴京街上看到國內外商人雲集','欣賞《清明上河圖》所繪大都的情形','他屬於「色目人」等級，被朝廷重用','逛市場要留意營業時間與地點的限制'],3,'(A)元代首都在大都(B)《清明上河圖》畫的是汴京(D)自宋代廢除坊市制度，出現許多不受營業時間與地點限制的夜市。')
ch('13 世紀時，義大利北部某教堂的神父告訴信徒，虔誠向上帝禱告並懺悔，便可躲過東方草原民族帶來的「黃禍」。上述中的「黃禍」，應該是指哪個民族向歐洲的擴張？',['蒙古','女真','匈奴','契丹'],1,'蒙古西征時，被歐洲人稱之為「黃禍」。')
ch('【進階】歷史課時，幾位同學探討有關忽必烈的重要事蹟，下列何人所言「有誤」？',['王韜：興兵滅南宋，統一全中國','李晴：建國號為元，定都於大都','郭靜：實施差別待遇的種族政策','楊康：派使者前往西域活絡貿易'],4,'漢武帝派張騫出使西域。')
ch('宋代由於人工磁化法（以磁石磨針鋒）的發明，使得指南針的應用範圍更廣。阿拉伯人將此技術傳入何處，開啟日後新航路的發現？',['美洲','非洲','澳洲','歐洲'],4,'阿拉伯人將指南針傳入歐洲。')
ch('伊斯蘭教創立於 7 世紀，在宋元時期，向亞洲各地擴張，下列相關敘述何者錯誤？',['阿拉伯商人來華貿易，於聚集地建立清真寺禮拜','到中國貿易的穆斯林商人，乃地位最低下的南人','因為暢通的海陸交通，使得穆斯林商人東來貿易','伊斯蘭文化中的天文、曆法和醫學影響中國深遠'],2,'元代穆斯林商人屬於色目人，地位僅次於蒙古人。')
ch('宋代是中國科學技術取得較大進展的時期，幾大發明的投入實用及大規模外傳均在此際，其中三項成就更是在航海、學術、戰爭方面有重大影響。上述所指是哪些成就？',['紙幣、造紙術、火藥','羅盤、青銅器、火藥','指南針、印刷術、火藥','青銅器、造紙術、火藥'],3,'(A)紙幣是交易媒介、造紙術於漢代已出現，青銅器為商周時期的器物。')
ch('【進階】正赫撰寫以蒙古為主題的報告，下列是其報告的部分內容，哪一項敘述有誤？',['鐵木真和繼位者發動三次西征','蒙古西征之後建立了四大汗國','蒙古對歐亞文化交流頗有貢獻','成吉思汗建立元朝並定都大都'],4,'(D)忽必烈建立元朝並定都大都。')
ch('【素養】拉帕：「我的祖國被征服了，我淪為被統治者，但比起其他民族的遭遇，我們還算幸運，得到統治階層的信任，把我們當助手，派我們處理財政、稅賦方面的職務。」由上述判斷，拉帕最有可能為何種身分？',['西晉時，移入中原的匈奴人','唐代時，旅居長安的突厥人','金國統治中原時的契丹人','元代統治中國時的西域人'],4,'元代統治中國時的西域人屬於「色目人」，朝廷多讓他們擔任財政職務。')
psg('歷史老師在上課時提供以下資料：\n資料一：宋朝與「甲國」原本因土地的管轄有紛爭，長年戰爭下，最後由宋朝皇帝親征後終於妥協。依照規定，宋朝交付甲國銀、絹，作為歲幣。訂定白溝河作為邊界，且為維護兩國和平，宋朝為兄、甲國為弟。\n資料二：宋朝與「乙國」在戰爭下進入混亂，宋朝皇帝遭乙國擄走，危難之下宋室南遷，於臨安另立新都致力抗衡，雙方形成長期對峙的局面。')
ch('文中資料一的甲國，應為下列哪一民族？',['契丹','匈奴','女真','蒙古'],1,'澶淵之盟是宋與契丹（遼）所訂。')
ch('【素養】關於文中資料二的乙國，下列何者正確？',['當時的領袖為成吉思汗','建國之後聯盟攻打甲國','崛起地點位於今日西域','最後滅亡於西夏的手上'],2,'(A)成吉思汗為蒙古人(C)位於東北(D)蒙古與南宋合作滅金國。')
ch('根據文中兩資料，當時的國際局勢呈現哪一特色？',['開始修築長城防禦外族','北亞草原民族勢力強盛','宋朝成為東亞秩序盟主','四大汗國突破歐亞疆域'],2,'北宋到南宋初期，亞洲北部民族興起，影響東亞局勢。')
ch('【素養】同學們針對文中兩份資料的內容進行討論，下列何者的說法正確？',['芙莉：資料一的背景應為永嘉之禍','魯夫：資料二的背景應為澶淵之盟','小桃：資料一當時親征的皇帝為趙匡胤','小吉：資料二與乙國的紛爭為靖康之禍'],4,'(A)澶淵之盟(B)背景為靖康之禍(C)宋真宗。')
endp()
psg('故宮在 2020 年特別規畫「四方來朝─職貢圖特展」，「職貢」是歷代中國對外交往的體制，意指朝貢國向宗主國──中國修職納貢，並接受朝覲、冊封與賞賜，以示臣服。展品中《契丹使朝聘》描繪在簽訂澶淵之盟後，契丹族前往朝廷拜見中國皇帝的場景，但主賓契丹使節卻被畫在畫作不起眼的左下角，顯見畫家要建構的是一個以中國為國際中心的圖像。')
ch('由文中提到的展品《契丹使朝聘》，可了解當時的國際局勢，畫中的契丹使節代表的是下列哪一政權？',['遼國','金國','西夏','蒙古帝國'],1,'契丹建立遼國。')
ch('文中畫作中接受契丹使節來朝聘的中國皇帝，是下列哪一位君王？',['漢武帝','唐太宗','宋真宗','元世祖'],3,'澶淵之盟是宋真宗時簽訂。')
ch('文中使節被畫在邊緣處，但其國家強盛時，曾經是東亞國際局勢的主導者，鄰近多國都向其稱臣納貢，但「最不可能」包括下列何者？',['女真','西夏','高麗','蒙古'],4,'當時蒙古尚未興起。')
endp()

sec('第14回 歷史 第三篇第4章 明清時期東亞世界的變動')
ch('小安是生活在 16 世紀時期的南洋居民，某日他跟隨著國家的使節前往傳說中的「天朝」，將國家的奇珍異寶獻給天朝的皇帝後，接受冊封並得以在天朝內進行商業買賣。上述互動應為下列何項政策？',['朝貢貿易','海禁政策','和親政策','驛站制度'],1,'外國向中國朝貢、接受冊封並得以進行貿易，為朝貢貿易。')
ch('【進階】下列兩份資料的統治者，應為哪一政權？（資料一：新疆在 18 世紀時，統治者平定當地後逐漸加深控制，並以「新的疆土」之稱於當地設省。資料二：西藏以前有圖博、吐蕃等稱呼，直到 18 世紀時，統治者平定當地起事，逐漸納入版圖，再更名為西藏。）',['唐朝','元朝','明朝','清朝'],4,'18 世紀時，將新疆、西藏納入版圖的為清朝。')
ch('下表為明代軍費與年度支出的統計表，下列何者「不是」導致軍費支出日益增加的原因？',['蒙古侵擾北方','女真人的進犯','倭寇騷擾沿海','西方列強侵略'],4,'明代的外患為北方蒙古、女真與沿海倭寇，西方列強侵略是清末之事。',img=P(27,1,185,1170,770,1380))
ch('在歷史上，明末清初的吳梅村一句「慟哭六軍俱縞素，衝冠一怒為紅顏」，說明了明代山海關守將何人降清，引清兵入關？',['鄭和','吳三桂','徐光啟','李自成'],2,'吳三桂引清兵入關。')
ch('【進階】阿青是一位生活在明代北京的雜貨商人，他「最不可能」有下列哪一經歷？',['在市場販售馬鈴薯','到專業市鎮購買商品','轉手景德鎮青花瓷盤','被官府強迫薙髮留辮'],4,'(D)清代的高壓統治政策。')
ch('元代末年，群雄並起，最後以出身民間而建立明代的是下列何人？',['吳三桂','朱元璋','李自成','鐵木真'],2,'朱元璋建立明朝。')
ch('明代自建國以後，北方始終處於「甲」的威脅之下，而東南沿海則苦於「乙」的侵擾。甲、乙依序應填入下列何者？',['突厥、流寇','蒙古、倭寇','女真、倭寇','契丹、流寇'],2,'明代北方有蒙古威脅，東南沿海有倭寇侵擾。')
ch('18 世紀時，當時歐洲的學者因為崇尚中國儒家風氣，改編了中國傳統民間故事。根據上述內容判斷，歐洲人接觸到中國儒家風氣，應與何種因素有關？',['耶穌會傳教士訪華後交流經典','蒙古西征時將經典帶入到歐洲','鄭和下西洋時與歐洲人有貿易','阿拉伯商人經商時帶回的經典'],1,'耶穌會傳教士將中國經典傳回歐洲。')
ch('某書為中國士大夫徐光啟與傳教士共同翻譯的歐洲典籍，成為當時中國人學習數學的教材。該典籍應為下列何者？',['《聖經》','《四書集注》','《回回藥方》','《幾何原本》'],4,'徐光啟與利瑪竇合譯《幾何原本》。')
ch('下列兩則事例反映出明清時期的哪一現象？（事例一：明太祖年間，官員趙伯寧上〈萬壽表〉，其中有「垂子孫而作則」句，因「作則」與「作賊」音似，遭處死。事例二：清世宗年間，徐駿因寫了「明月有情還顧我，清風無意不留人」被處死。）',['禁止私人講學論政','重武輕文貶低儒生','以文字獄摧殘文人','科舉取士出現弊端'],3,'明清時期，統治者都曾以文字獄迫害士人。')
ch('15、16 世紀，歐洲商人到東亞貿易，他們帶著□□大量購買中國的絲綢、瓷器等商品，造成中國貨幣經濟產生重大變化。上文提到的□□應為下列何者？',['白銀','黃金','青銅','紙幣'],1,'歐洲商人以白銀購買中國商品，白銀大量流入中國。')
ch('同樣由來自於關外的少數民族所統治，清代國祚卻較蒙古人的元代為長，因為它對漢族並非單純地征服、鎮壓，而是實施一套高壓與懷柔相結合的統治政策。下列哪一政策是屬於懷柔的部分？',['舉行科舉','大興文字獄','採九品任官的作法','強迫漢人薙髮留辮'],1,'清代舉行科舉，攏絡漢人士人。')
ch('某部電影內容描述 17 世紀時，在日本傳教的耶穌會傳教士遭到指控背棄了教義。其學生為了證實老師的清白前往日本，但在過程中看到了他們信仰的宗教在日本發展的困境。上述主角等人信仰的宗教，最可能為下列何者？',['基督新教','伊斯蘭教','天主教','佛教'],3,'耶穌會屬於天主教。')
ch('中國至唐代以來，海外貿易就相當發達，但明代與清初政府均曾下令實施海禁政策，嚴禁人民出海。其防堵的對象分別為何？',['明─流寇，清─倭寇','明─荷蘭，清─西班牙','明─倭寇，清─臺灣鄭氏','明─臺灣鄭氏，清─倭寇'],3,'明代海禁防倭寇，清初海禁防臺灣鄭氏。')
ch('【進階】15 世紀末，歐洲人發現了通往亞洲的新航路，陸續前來中國進行貿易。明代中期到清初對外關係的特徵「不包括」下列何者？',['對外經濟、文化等交流頻繁','政府閉關自守禁絕對外貿易','白銀大量流入逐漸取代紙幣','交易商品以絲綢、瓷器為主'],2,'(B)明清採朝貢貿易，並未完全禁絕對外貿易。')
ch('傳教士來到中國，將西方的科技帶入，並且也將中國典籍、園林建築傳回歐洲，其中的西方科技「不包含」下列何者？',['幾何學','天文曆法','軍事科技','活字印刷術'],4,'活字印刷術是中國宋代畢昇所發明。')
ch('隨著大航海時代來臨，東亞與西方曾有廣泛的文化交流，但後來卻又因故中斷交流，例如：日本在 17 世紀實施鎖國政策，限制通商與傳教，只允許中國、荷蘭商船到何地貿易？',['東京','大阪','京都','長崎'],4,'日本鎖國時只開放長崎與中國、荷蘭貿易。')
ch('【素養】「張生是明代人，（甲）平常聽聞北方蒙古進犯，後來又聽說不要到東南沿海活動，（乙）因為有流寇在海上劫掠。（丙）某天他跟友人到夜市逛逛，（丁）幸運地買到精緻的景德鎮瓷器，高興地捧著瓷器回家。」上述是峻碩的歷史作業，何者敘述「有誤」？',['甲','乙','丙','丁'],2,'(乙)應該是「倭寇」在海上劫掠。')
ch('凱瑜晚餐時，在餐桌上看到花生、玉米、馬鈴薯等食材，想起老師曾提到這些作物原產於美洲，經過東西文化交流，才會出現在我們的餐桌上。關於這些食物的傳播歷程，下列何項敘述正確？',['荷蘭治臺時引進臺灣，再經由臺灣傳至中國','鄭和出使「西洋」時，從中南美洲帶回中國','蒙古三次西征橫跨歐亞，促進異國作物交流','歐洲商人到亞洲貿易，將美洲作物傳入中國'],4,'歐洲商人到亞洲貿易，將美洲作物傳入中國。')
ch('【進階】滿清以少數民族作為統治者，故針對不同的民族實行多元的統治政策，其中何者並非針對統治漢人所採取的策略？',['大興文字獄，箝制其思想','保護支持其宗教藉以拉攏','舉行科舉，特別晉用士人','強迫兩族人都要薙髮留辮'],2,'並無以此項措施籠絡漢人。')
ch('【素養】佑軒以「明清時期的對外貿易」為主題，撰寫歷史報告，下列哪一項資料會出現在他的報告中？',['明代政府首次設立市舶司，管理海上貿易','對外貿易使用的貨幣，是紙幣與銅錢並用','實施海禁，以「朝貢貿易」進行對外貿易','15 世紀初期，出現「海商集團」影響貿易'],3,'(A)唐代首次設立市舶司(B)東亞各國和西方國家以白銀為交易媒介(D)16 世紀後期出現「海商集團」。')
ch('【進階】明清之際，西方文物曾大量傳入中國，而中國思想與技術也傳至西方，這樣的文化交流，因清代發生哪一事件而被迫中斷？',['厲行海禁政策，阻止外人入境','大興文字獄，排斥西學與洋教','實施禁教，驅逐西洋的傳教士','積極經營西域，防止歐人東進'],3,'雍正皇帝因傳教士涉及宮廷政爭，下令將傳教士逐出中國，中西文化交流因此中斷。')
ch('【素養】15 世紀末，葡萄牙人發現了經由非洲南端通往亞洲的新航路，引發地理大發現的風潮，對世界各地的歷史發展產生重大影響。下列何者並非此風潮對中國造成的影響？',['鄭和率艦隊多次出使西洋','西方的近代科技傳入中國','白銀自海外大量輸入中國','天主教耶穌會傳教士來華'],1,'(A)鄭和下西洋在 15 世紀初，與地理大發現無關。')
ch('【素養】「1980 年在北京永定門外沙子口一個建築工地上，施工者掘到古錢一枚，其銅色金黃，寬輪光背，『永昌通寶』4 個字清晰可辨。考古學者判斷，此幣應為明末農民起義軍領袖李自成所鑄。」下列何者與該位領袖最為相關？',['帶領流寇攻陷北京，明代亡','驅除蒙古人，結束元朝統治','其武裝力量的海商，進行東亞走私貿易','與吳三桂合作，攻陷北京，遂自立為王'],1,'1644 年李自成攻陷北京，明代滅亡，不久後明將吳三桂聯手清兵擊敗李自成。')
psg('「雍正王朝」這部歷史劇以正史的拍攝手法，描寫諸皇子間的鬥爭、機詐，讓雍正脫穎而出，以及雍正即位後，在阻絆中大力推動改革，最後勞累而死的過程。該劇創下極高收視率，一改過往雍正的電視反派形象，甚至讓許多觀眾開始研究這段歷史。')
ch('文中的故事背景，是由哪一民族所建立的朝代？',['契丹','匈奴','女真','蒙古'],3,'清朝由女真（滿洲）人建立。')
ch('雍正在經歷繼承權之爭後登基，立即下令禁教，這與下列哪一原因最密切相關？',['耶穌會允許教徒祭祖','傳教士涉及宮廷政爭','儒家經典被傳到歐洲','傳教士拒絕薙髮留辮'],2,'雍正因傳教士涉及宮廷政爭而禁教。')
ch('【素養】根據上文，在觀看這部連續劇時，最可能會看到下列哪一場景？',['派施琅攻臺並將臺灣納入版圖','文人的詩句因得罪皇帝被判刑','李自成的崛起使皇家出兵平定','皇帝為了穩固政權遷都至北京'],2,'清代有諸多文字獄發生，故選(B)。(A)康熙皇帝時(C)為明末(D)為明成祖。')
endp()
psg('附圖是 15 世紀初期，鄭和下西洋的航海路線圖，是歷時 29 年的七場連續的大規模遠洋航海，象徵著中國航海史上的一個高峰。')
ch('圖中的航行路線主要是發生於哪位皇帝在位時？',['漢武帝','唐太宗','宋真宗','明成祖'],4,'明成祖派遣鄭和出使西洋。')
ch('由附圖判斷，鄭和下西洋的「西洋」是指今日哪些地區？',['東南亞、大西洋','大西洋、印度洋','東南亞、印度洋','太平洋、大西洋'],3,'由航線圖可知西洋指東南亞、印度洋。',img=P(28,3,95,1005,635,1370))
ch('附圖包含歷次出使的艦隊航行範圍，可知其航行路線最遠抵達何地？',['美洲西岸','印度南岸','歐洲西部','非洲東岸'],4,'由航線圖可知最遠抵達非洲東岸。',img=P(28,3,95,1005,635,1370))
ch('【進階】此大規模的航海活動影響深遠，下列何者「不是」其所造成的影響？',['沿海居民移居東南亞','明代向南方擴展版圖','南海諸國向明帝國進貢','擴大了朝貢貿易的規模'],2,'鄭和下西洋後，明代並未向南方擴展版圖。')
endp()

sec('第15回 歷史 第三篇3～4章 複習')
ch('日治時期蓬萊米的培植是臺灣農業史上的大事；宋代農業的重大發展則是自何處引進早熟稻，使稻米產量大為增加？',['越南','美洲','西藏','日本'],1,'宋代自占城（越南）引進早熟稻。')
ch('希臘人通過翻譯阿拉伯人的書籍才知道火藥，火藥武器是通過戰爭傳到阿拉伯國家。火藥源於中國，何時開始普遍運用於軍事上？',['秦代','宋代','元代','明代'],2,'宋代火藥普遍運用於軍事上。')
ch('南宋大儒朱熹集理學之大成，所著的《四書集注》成為元代之後科舉考試的定本。該書的內容與下列何者較有關？',['儒學','法學','科學','數學'],1,'儒家學者融合佛學等思想，形成理學。')
ch('歷史老師為了增進同學解讀歷史圖表的能力，以圖來說明，由圖中內容判斷，老師講解的主題最可能為下列何者？',['鄭和艦隊出使西洋路線圖','明代中後期流寇活動區域圖','蒙古西征路線及元代疆域圖','15 世紀歐洲人貿易路線圖'],1,'圖為鄭和下西洋的航海路線。',img=P(29,1,230,1155,745,1500))
ch('明代中期，歐洲人發現到東方的新航路，稱之為地理大發現。這樣的成就與宋代的哪一種科技西傳關係最密切？',['火藥','造紙術','指南針','印刷術'],3,'指南針西傳有助於航海。')
ch('【進階】清代為鞏固政權，採取高壓與懷柔並行的統治政策。清代實施高壓政治箝制漢人所使用的手段中，「不包括」下列何者？',['消滅反清勢力','強迫薙髮留辮','廢除科舉考試','大興文字獄'],3,'(C)舉行科舉以籠絡人心。')
ch('隨著大航海時代來臨，明末清初來華的傳教士對中西文化交流貢獻頗大，但清代哪一位皇帝因傳教士涉及宮廷政爭而將傳教士逐出中國？',['康熙皇帝','雍正皇帝','明太祖','明成祖'],2,'雍正皇帝因傳教士涉及宮廷政爭而禁教。')
